```javascript
function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];
    if (isPrime(num)) {
      if (i < 10) {
        console.log(num);
      } // чтобы вывести число, если оно простое, в начале функции, и если оно не превышает 100, чтобы избежать вывода при тестировании массивов с большим количеством элементов
    }
  }
}

